function CrimsonPermission(a,key,fallback)
 if a.permissions then return a.permissions[key]==true end
 return fallback==true
end
local modules={
 case={'reports_view','reports_create','reports_delete'},incident={'reports_view','reports_create','reports_delete'},
 document={'reports_view','reports_create','reports_delete'},recording={'reports_view','reports_create','reports_delete'},
 note={'profiles_view','profiles_edit','profiles_edit'},warrant={'warrants_view','warrants_create','warrants_delete'},
 vehicle_flag={'vehicles_view','vehicles_edit','vehicles_edit'},weapon={'vehicles_view','vehicles_edit','vehicles_edit'},
 business_license={'business_view','business_manage','business_manage'},business_note={'business_view','business_manage','business_manage'},
 dispatch={'reports_view','reports_create','reports_delete'},
}
function CrimsonModulePermission(a,kind,mode,fallback)
 if not a.permissions then return fallback==true end
 local keys=modules[kind]
 return keys and a.permissions[keys[mode]]==true or false
end
